import semver from "semver";
import { satisfies, maxSatisfying } from "/private/tmp/hb/runsB/pi-1/src/semver.ts";
const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)];
const ids = ["0","1","2","3","10","x","X","*","01"];
const pre = ["", "", "", "-0", "-alpha", "-beta.2", "-beta.10", "-a.b", "-1", "-rc.1"];
const build = ["", "", "", "+b", "+001.x"];
const part = () => { const n = pick([1,2,3,3,3]); const p = Array.from({length:n},()=>pick(ids)).join("."); return pick(["","","v","="]) + p + (n===3?pick(pre)+pick(build):""); };
const comp = () => pick(["","","^","~","~>",">",">=","<","<=","=","^ ","> "]) + part();
const set = () => Math.random() < 0.15 ? `${part()} - ${part()}` : Array.from({length: pick([1,1,2,3])}, comp).join(pick([" ","  "]));
const range = () => Array.from({length: pick([1,1,2])}, set).join(pick([" || ","||"]));
const vnum = ["0","1","2","3","10"];
const ver = () => [pick(vnum),pick(vnum),pick(vnum)].join(".") + pick(pre) + pick(build);
let bad = 0;
for (let i = 0; i < 200000; i++) {
  const r = range(); const v = ver();
  const a = semver.satisfies(v, r), b = satisfies(v, r);
  if (a !== b && bad++ < 20) console.log("sat", JSON.stringify(v), JSON.stringify(r), a, b);
  if (i % 20 === 0) { const vs = Array.from({length: 8}, ver); const x = semver.maxSatisfying(vs, r), y = maxSatisfying(vs, r); if (x !== y && bad++ < 20) console.log("max", r, vs, x, y); }
}
console.log("bad", bad);
EOF
